import { MeshStandardNodeMaterial, MeshPhysicalNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, vec3, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as text from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, SphereGeometry, CylinderGeometry, Color, DoubleSide } = ctx.THREE;

  // ---------- Root ----------
  const root = new Group();
  root.name = 'OrreryNode';

  // ---------- Backdrop Gradient ----------
  const backdropGeom = new PlaneGeometry(7, 6);
  const gradientStops = (config.visualSpec?.colors?.gradientStops) || [
    { at: 0, hex: '#0b0b10' },
    { at: 0.65, hex: '#101017' },
    { at: 1, hex: '#16161d' }
  ];
  // Build vertical gradient node
  let gradColor = vec3(...hexToRgb(gradientStops[0].hex));
  for (let i = 1; i < gradientStops.length; i++) {
    const prev = gradientStops[i - 1];
    const cur = gradientStops[i];
    const t = smoothstep(prev.at, cur.at, uv().y);
    gradColor = mix(gradColor, vec3(...hexToRgb(cur.hex)), t);
  }
  const backdropMat = new MeshStandardNodeMaterial({
    color: gradColor,
    metalness: 0,
    roughness: 1,
    side: DoubleSide,
    transparent: false
  });
  const backdrop = new Mesh(backdropGeom, backdropMat);
  backdrop.position.set(0, 0, -3);
  root.add(backdrop);

  // ---------- Gear Group ----------
  const gearGroup = new Group();
  root.add(gearGroup);

  // Primary gear GLB
  ctx.glbLoader.loadGLB(config.meshUrl).then(gltf => {
    gearGroup.add(gltf.scene);
  });

  // Secondary gear instance
  const secondaryGear = new Group();
  secondaryGear.position.set(1.15, 0.35, -0.1);
  gearGroup.add(secondaryGear);
  ctx.glbLoader.loadGLB(config.meshUrl).then(gltf => {
    const clone = gltf.scene.clone(true);
    secondaryGear.add(clone);
    const scale = 0.9 / 1.6; // primary diameter ~1.6
    secondaryGear.scale.setScalar(scale);
  });

  // ---------- Jewel Pivot ----------
  const jewelGeom = new SphereGeometry(0.12, 32, 32);
  const jewelMat = new MeshPhysicalNodeMaterial({
    color: new Color('#ff2a38'),
    transmission: 0.6,
    ior: 1.76,
    emissive: new Color('#ff2a38'),
    emissiveIntensity: 1.8,
    roughness: 0.25,
    metalness: 0
  });
  const jewel = new Mesh(jewelGeom, jewelMat);
  jewel.position.set(0, 0, 0);
  gearGroup.add(jewel);

  // ---------- Arbor Shafts ----------
  const shaftGeom = new CylinderGeometry(0.05, 0.05, 0.8, 16);
  const shaftMat = new MeshStandardNodeMaterial({
    color: new Color('#16161d'),
    metalness: 0.55,
    roughness: 0.5,
    clearcoat: 0.2,
    clearcoatRoughness: 0.3
  });
  const primaryShaft = new Mesh(shaftGeom, shaftMat);
  primaryShaft.rotation.x = Math.PI / 2;
  gearGroup.add(primaryShaft);

  const secondaryShaft = new Mesh(shaftGeom, shaftMat);
  secondaryShaft.rotation.x = Math.PI / 2;
  secondaryShaft.position.copy(secondaryGear.position);
  gearGroup.add(secondaryShaft);

  // ---------- Contact Shadow ----------
  const shadowGeom = new PlaneGeometry(2.6, 1.2);
  const shadowMat = new MeshBasicNodeMaterial({
    color: new Color('#000000'),
    opacity: 0.5,
    transparent: true,
    depthWrite: false
  });
  const shadow = new Mesh(shadowGeom, shadowMat);
  shadow.position.set(0, -1.2, 0);
  shadow.rotation.x = -Math.PI / 2;
  root.add(shadow);

  // ---------- Text ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textGroup = new Group();
  root.add(textGroup);
  items.forEach(item => {
    const opts = {
      fontSize: item.typography?.fontSize,
      color: config.visualSpec?.colors?.paper || '#e8ecf2',
      align: 'center',
      letterSpacingPx: item.typography?.letterSpacing ?? 0
    };
    const txt = ctx.fontAtlas.createText(item.text, opts);
    txt.position.z = 0.01; // avoid z‑fighting with backdrop
    if (item.role === 'headline') {
      txt.position.set(0, -1.7, 0);
    } else if (item.role === 'caption') {
      txt.position.set(0, -2.1, 0);
    }
    textGroup.add(txt);
  });

  // ---------- Cinematic Primitives ----------
  const cleanupFns = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach(p => {
      const prim = ctx.primitives[p.name];
      if (prim) {
        const result = prim(root, p.params);
        if (result?.timeline) cleanupFns.push(() => result.timeline.kill());
        if (result?.cleanup) cleanupFns.push(result.cleanup);
      }
    });
  }

  // ---------- Cleanup ----------
  root.userData.cleanup = () => {
    // Dispose geometries & materials
    backdrop.geometry.dispose();
    backdrop.material.dispose();
    jewel.geometry.dispose();
    jewel.material.dispose();
    shaftGeom.dispose();
    shaftMat.dispose();
    shadow.geometry.dispose();
    shadow.material.dispose();
    // Dispose any GLB resources when they become available (Three.js handles it)
    cleanupFns.forEach(fn => fn());
  };

  // ---------- Handlers ----------
  root.userData.handlers = {};

  return root;
}

// Helper: hex string to normalized RGB array
function hexToRgb(hex) {
  const v = parseInt(hex.slice(1), 16);
  return [(v >> 16 & 255) / 255, (v >> 8 & 255) / 255, (v & 255) / 255];
}
